namespace CuteMouseEffects {
static class MagicPalette {
 public static readonly Color Back=Color.FromArgb(235,230,219),Card=Color.FromArgb(247,242,232),CardLow=Color.FromArgb(227,220,207),Side=Color.FromArgb(38,53,47),SideHot=Color.FromArgb(54,75,66),SideChosen=Color.FromArgb(65,91,78),Ink=Color.FromArgb(50,54,51),Soft=Color.FromArgb(104,105,99),Light=Color.FromArgb(239,235,223),Mint=Color.FromArgb(111,177,132),MintDark=Color.FromArgb(70,125,91),Pink=Color.FromArgb(215,113,132),Yellow=Color.FromArgb(226,188,80),Sky=Color.FromArgb(102,168,183),Track=Color.FromArgb(207,199,184);
 public static GraphicsPath Round(Rectangle r,int d){var p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}

class MagicCard:Panel {
 public Color Fill=MagicPalette.Card,Canvas=MagicPalette.Back;public int Radius=22;
 public MagicCard(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
 protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Canvas);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;var shadow=new Rectangle(3,5,Width-7,Height-8);using(var p=MagicPalette.Round(shadow,Radius))using(var b=new SolidBrush(MagicPalette.CardLow))g.FillPath(b,p);var face=new Rectangle(0,0,Width-7,Height-8);using(var p=MagicPalette.Round(face,Radius))using(var b=new SolidBrush(Fill))g.FillPath(b,p);base.OnPaint(e);}
}

class MagicBrand:Control {
