}

class MagicNav:Control {
 public int Kind;public Color Accent=MagicPalette.Pink;bool chosen,hot,down;
 public bool Chosen{get{return chosen;}set{chosen=value;Invalidate();}}
 public MagicNav(){Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
 protected override void OnMouseEnter(EventArgs e){hot=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hot=false;down=false;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Left){down=true;Invalidate();}base.OnMouseDown(e);}protected override void OnMouseUp(MouseEventArgs e){down=false;Invalidate();base.OnMouseUp(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(MagicPalette.Side);g.SmoothingMode=SmoothingMode.AntiAlias;Color fill=chosen?MagicPalette.SideChosen:(hot?MagicPalette.SideHot:MagicPalette.Side);if(down)fill=ControlPaint.Dark(fill);using(var p=MagicPalette.Round(new Rectangle(4,2,Width-8,Height-4),20))using(var b=new SolidBrush(fill))g.FillPath(b,p);if(chosen)using(var b=new SolidBrush(Accent))g.FillRectangle(b,4,17,4,22);using(var b=new SolidBrush(Accent))g.FillEllipse(b,20,14,30,30);using(var pen=new Pen(MagicPalette.Light,2)){float x=35,y=29;if(Kind==0){g.DrawEllipse(pen,x-6,y-6,12,12);g.DrawLine(pen,x,y-10,x,y-7);g.DrawLine(pen,x,y+7,x,y+10);}else if(Kind==1){g.DrawLine(pen,x-7,y-8,x+7,y+7);g.DrawLine(pen,x-7,y-8,x-3,y+7);g.DrawLine(pen,x-3,y+7,x+1,y+3);}else if(Kind==2){g.DrawLine(pen,x-8,y+6,x-2,y-4);g.DrawLine(pen,x-2,y-4,x+2,y+2);g.DrawLine(pen,x+2,y+2,x+8,y-7);}else{g.DrawEllipse(pen,x-7,y-7,14,14);g.DrawEllipse(pen,x-2,y-2,4,4);}}using(var f=new Font("Microsoft YaHei UI",10,FontStyle.Bold))using(var b=new SolidBrush(MagicPalette.Light))g.DrawString(Text,f,b,66,18);}
}

class MagicSlider:Control {
 int minimum,maximum=100,value;public Color Accent=MagicPalette.Mint;public event EventHandler ValueChanged;
 public int Minimum{get{return minimum;}set{minimum=value;Value=this.value;}}public int Maximum{get{return maximum;}set{maximum=Math.Max(minimum+1,value);Value=this.value;}}public int Value{get{return value;}set{int n=Math.Max(minimum,Math.Min(maximum,value));if(n==this.value)return;this.value=n;Invalidate();if(ValueChanged!=null)ValueChanged(this,EventArgs.Empty);}}
 public MagicSlider(){Cursor=Cursors.Hand;TabStop=true;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(MagicPalette.Card);g.SmoothingMode=SmoothingMode.AntiAlias;int l=10,r=Width-10,y=Height/2;float u=(value-minimum)/(float)(maximum-minimum);int x=l+(int)((r-l)*u);using(var p=new Pen(MagicPalette.Track,5)){p.StartCap=p.EndCap=LineCap.Round;g.DrawLine(p,l,y,r,y);}using(var p=new Pen(Accent,5)){p.StartCap=p.EndCap=LineCap.Round;g.DrawLine(p,l,y,x,y);}using(var b=new SolidBrush(Color.FromArgb(178,168,150)))g.FillEllipse(b,x-8,y-5,17,17);using(var b=new SolidBrush(MagicPalette.Card))g.FillEllipse(b,x-8,y-8,17,17);using(var p=new Pen(Accent,2))g.DrawEllipse(p,x-8,y-8,17,17);}
 protected override void OnMouseDown(MouseEventArgs e){SetX(e.X);Focus();base.OnMouseDown(e);}protected override void OnMouseMove(MouseEventArgs e){if(e.Button==MouseButtons.Left)SetX(e.X);base.OnMouseMove(e);}void SetX(int x){float u=Math.Max(0,Math.Min(1,(x-10)/(float)Math.Max(1,Width-20)));Value=minimum+(int)Math.Round((maximum-minimum)*u);}
}

class MagicToggle:Control {
 bool value,down;public event EventHandler CheckedChanged;public bool Checked{get{return value;}set{if(this.value!=value){this.value=value;Invalidate();if(CheckedChanged!=null)CheckedChanged(this,EventArgs.Empty);}}}
 public MagicToggle(){Cursor=Cursors.Hand;Size=new Size(58,30);SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Click+=delegate{Checked=!Checked;};}
