}

class MagicThemePicker:Control {
 string selectedId="warm";int hot=-1;public event EventHandler SelectionChanged,CustomRequested;
 public string SelectedId{get{return selectedId;}set{string id=EffectThemes.Find(value).Id;if(id==selectedId)return;selectedId=id;Invalidate();}}
 public MagicThemePicker(){Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
 protected override void OnMouseMove(MouseEventArgs e){int n=Math.Max(0,Math.Min(EffectThemes.All.Length-1,e.X/Math.Max(1,Width/EffectThemes.All.Length)));if(n!=hot){hot=n;Invalidate();}base.OnMouseMove(e);}protected override void OnMouseLeave(EventArgs e){hot=-1;Invalidate();base.OnMouseLeave(e);}
 protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Left){int n=Math.Max(0,Math.Min(EffectThemes.All.Length-1,e.X/Math.Max(1,Width/EffectThemes.All.Length)));if(EffectThemes.All[n].Id=="custom"){if(CustomRequested!=null)CustomRequested(this,EventArgs.Empty);}else{SelectedId=EffectThemes.All[n].Id;if(SelectionChanged!=null)SelectionChanged(this,EventArgs.Empty);}}base.OnMouseDown(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(MagicPalette.Back);g.SmoothingMode=SmoothingMode.AntiAlias;int cell=Width/EffectThemes.All.Length;for(int i=0;i<EffectThemes.All.Length;i++){var t=EffectThemes.All[i];var r=new Rectangle(i*cell+3,2,cell-7,Height-6);bool chosen=t.Id==selectedId;using(var p=MagicPalette.Round(r,18))using(var b=new SolidBrush(chosen?Color.FromArgb(255,249,239):(i==hot?Color.FromArgb(242,237,227):MagicPalette.Card)))g.FillPath(b,p);if(chosen)using(var p=MagicPalette.Round(new Rectangle(r.X+1,r.Y+1,r.Width-2,r.Height-2),17))using(var pen=new Pen(t.Primary,2.2f))g.DrawPath(pen,p);int cy=29;using(var b=new SolidBrush(t.Shadow))g.FillEllipse(b,r.X+15,cy-8,16,16);using(var b=new SolidBrush(t.Primary))g.FillEllipse(b,r.X+28,cy-10,20,20);using(var b=new SolidBrush(t.Secondary))g.FillEllipse(b,r.X+44,cy-8,16,16);using(var f=new Font("Microsoft YaHei UI",8.5f,chosen?FontStyle.Bold:FontStyle.Regular))TextRenderer.DrawText(g,t.Name,f,new Rectangle(r.X+3,51,r.Width-6,25),MagicPalette.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);}}
}
