 string Format(MagicSlider b){if(b==trailWidth||b==effectSize||b==particles)return (b.Value/100f).ToString("0.00")+" 倍";if(b==trailLife||b==frameRate)return b.Value+" 毫秒";return b.Value.ToString();}int Clamp(int v,MagicSlider b){return Math.Max(b.Minimum,Math.Min(b.Maximum,v));}
 internal void SyncFromHost(){syncing=true;trailWidth.Value=Clamp((int)Math.Round(host.TrailScaleValue*100),trailWidth);trailLife.Value=Clamp(host.TrailLifeValue,trailLife);effectSize.Value=Clamp((int)Math.Round(host.EffectScaleValue*100),effectSize);particles.Value=Clamp((int)Math.Round(host.ParticleScaleValue*100),particles);frameRate.Value=Clamp(host.FrameMsValue,frameRate);maxPoints.Value=Clamp(host.MaxTrailValue,maxPoints);maxSamples.Value=Clamp(host.MaxSamplesValue,maxSamples);enabledToggle.Checked=host.EffectsEnabled;startupToggle.Checked=StartupEnabled();themePicker.SelectedId=host.ThemeIdValue;cursorPicker.ThemeId=host.ThemeIdValue;cursorPicker.SelectedId=host.CursorShapeIdValue;cursorToggle.Checked=host.CursorEffectEnabled;brand.SetRunning(host.EffectsEnabled);syncing=false;}
 void Defaults(){themePicker.SelectedId="warm";cursorPicker.ThemeId="warm";cursorPicker.SelectedId="swirl";host.SetTheme("warm");host.SetCursorShape("swirl");trailWidth.Value=100;trailLife.Value=460;effectSize.Value=100;particles.Value=100;frameRate.Value=30;maxPoints.Value=120;maxSamples.Value=9;cursorToggle.Checked=true;}void SaveAll(){try{host.SetCursorShape(cursorPicker.SelectedId);host.SetCursorEffect(cursorToggle.Checked);host.ApplySettings(trailWidth.Value/100f,trailLife.Value,effectSize.Value/100f,particles.Value/100f,frameRate.Value,maxPoints.Value,maxSamples.Value);SetStartup(startupToggle.Checked);SyncFromHost();MessageBox.Show(this,"设置已经保存并立即生效。","保存成功",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(this,"保存失败："+ex.Message,"保存设置",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 bool StartupEnabled(){try{using(var k=Registry.CurrentUser.OpenSubKey(RunPath,false))return k!=null&&k.GetValue(RunName)!=null;}catch{return false;}}void SetStartup(bool value){using(var k=Registry.CurrentUser.CreateSubKey(RunPath)){string q=Convert.ToChar(34).ToString();if(value)k.SetValue(RunName,q+Application.ExecutablePath+q+" --minimized");else k.DeleteValue(RunName,false);}}
 void PanelClosing(object s,FormClosingEventArgs e){if(!allowClose&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Hide();}}internal void ForceClose(){allowClose=true;Close();}protected override void Dispose(bool disposing){if(disposing&&avatar!=null)avatar.Dispose();if(disposing&&avatarStream!=null)avatarStream.Dispose();base.Dispose(disposing);}
}
